// Per-pack parameters moved from the top-level `packConfig` key onto each pack's
// `packs` entry as `config` (#278). The write side is bootstrap step 4d (the fold
// snippet baselining re-runs on every member), not this record — like the pack
// seeds, this record is the transition's TELEMETRY: legacyPresent reads a member's
// declaration and reports it still on the old shape while a top-level `packConfig`
// key remains, so the retire pass shows fleet-wide convergence.
//
// retire:'manual' — the read-side tolerance lives INLINE, not resolver-driven:
// loadConfig still accepts the key (CONFIG_KEYS) and overlays it under the entry
// view (engine/checks/helpers/repo-context.mjs), and the fleet census's config reader falls back
// to it. Deleting this record alone would strand those. When the retire pass
// reports zero repos on the legacy shape, drop it all in one deliberate change:
// this record, bootstrap step 4d, 'packConfig' from CONFIG_KEYS + the overlay
// (a straggler then gets the blocking unknown-setting error, the settings-validity
// gate becoming the enforcement), and the census fallback.
export default {
  id: 'pack-entry-config',
  landed: '2026-07-13',
  summary: "per-pack parameters moved from the top-level packConfig key onto each pack's packs entry as config (one-time fold; key stays readable until retirement)",
  legacyPresent: async (exists, read) => {
    const raw = await read('.claudinite-checks.json');
    if (raw == null) return false; // no declaration to read — don't hold retirement on it
    try {
      const parsed = JSON.parse(raw);
      return !!parsed && typeof parsed === 'object' && !Array.isArray(parsed) && 'packConfig' in parsed;
    } catch {
      return false; // unparsable — don't block retirement
    }
  },
  retire: 'manual',
};

== .claudinite/shared/migrations/active_migrations/2026-07-15-local-packs-enablement.mjs ==
// Enable a repo's own local packs (.claudinite/local_packs/ — tracked project
// prose/checks/skills/run_daily the engine runs alongside the canon). Two pieces
// of member-side plumbing must be in place before a repo can safely COMMIT local
// packs, and BOTH ride baselining (not this record):
//   1. the tracked sync hook must preserve local_packs/ across its dir swap —
//      baselining refreshes the member's tracked mount/sync-claudinite.sh from the
//      canon every run (the canon copy carries the preserve block); and
//   2. .gitignore must re-include .claudinite/local_packs/ — bootstrap.md step 3
//      (idempotent, re-applied by baselining) appends the negation.
// The canon commit that ships those touches mount/ and bootstrap.md, so
// canonChanged fires fleet-wide and baselining converges every member the first
// night after — no per-repo content is materialized here (a project AUTHORS its
// own local packs; the move of existing capture is a judgment task carried by the
// project-instructions and growth-extract skills, never a mechanical alias).
//
// This record is therefore TELEMETRY ONLY: the retire pass reports how many
// members still carry the pre-enablement hook, so the owner can see when the whole
// fleet is safe to author local packs in. `legacyPresent` reads the member's
// tracked hook and returns true while it lacks the local_packs preserve block.
//
// retire: 'manual' — the enablement lives in baselining + bootstrap, not here, so
// this record holds no tolerance to strand; retire it by hand once the retire pass
// reports zero members on the legacy shape.
export default {
  id: 'local-packs-enablement',
  landed: '2026-07-15',
  summary: 'members preserve + track .claudinite/local_packs/ (sync-hook preserve via baselining, gitignore via bootstrap)',
  legacyPresent: async (exists, read) => {
    const hook = await read('.claudinite/mount/sync-claudinite.sh');
    if (hook == null) return false; // pre-mount shape — the mount-folder migration tracks that, not this
    // Converged once the tracked hook carries the preserve block for local_packs.
    return !hook.includes('$dest/local_packs');
  },
  retire: 'manual',
};

== .claudinite/shared/migrations/active_migrations/2026-07-19-local-pack-namespace.mjs ==
// Namespace local-pack declarations: a repo's own pack (.claudinite/local_packs/<name>/)
// is declared in .claudinite-checks.json by its namespaced token `local_packs/<name>`,
// not a bare id — self-documenting, and a canon id can never be claimed by accident
// (the bare form shared the canon namespace; a collision was only CAUGHT by the
// discoverPacks shadow guard, never prevented).
//
// Seed-style, like grow-with-claudinite-seed: the WRITE rides baselining — its
// declaration-normalization step runs in the member checkout (which knows which
// declared ids are local packs) and rewrites any bare local-pack declaration to the
// namespaced form (see the baselining worker doc). This record holds no ops of its
// own; it is the convergence telemetry. The engine accepts BOTH forms throughout (and
// after — packEntryId's strip is the permanent parser, not a tolerance this record
// carries), so retiring strands nothing.
//
// legacyPresent: a member still declares a bare id (string entry or entry-object id,
// no `local_packs/` prefix) whose pack lives in its own .claudinite/local_packs/ tree.
// A bare id with no such local pack is a canon declaration — not this record's business.
// retire: 'auto' — self-retires once the fleet has converged and stayed quiet a cycle.
export default {
  id: 'local-pack-namespace',
  landed: '2026-07-19',
  summary: 'local-pack declarations namespaced as local_packs/<name> (baselining rewrites bare ids; the engine accepts both forms)',
  legacyPresent: async (exists, read) => {
    const raw = await read('.claudinite-checks.json');
    if (raw == null) return false;
    let packs;
    try { ({ packs } = JSON.parse(raw)); } catch { return false; }
    if (!Array.isArray(packs)) return false;
    for (const e of packs) {
      const id = typeof e === 'string' ? e : e?.id;
      if (typeof id !== 'string' || id.startsWith('local_packs/')) continue;
      if (await exists(`.claudinite/local_packs/${id}/pack.mjs`)) return true;
    }
    return false;
  },
  retire: 'auto',
};

== .claudinite/shared/migrations/active_migrations/2026-07-19-pack-independence.mjs ==
// Pack independence (extending.md; the canon-side `pack-independence` barrier):
// packs no longer import each other's code — a fixed folder-barrier is now
// CONTRIBUTED as manifest data (`requires` the mechanism pack +
// `contributes` on pack.mjs; the engine builds the rule) and the shared
// path/migration helpers moved into the vendored engine lib (engine/checks/helpers/).
// The old code-composition export (`defineBarrier`) is gone.
//
// Canon-side the conversion is complete (rule first, then the fixes — one
// commit each). Member-side there are no mechanical ops: nothing in a
// consumer's tree is renamed or rewritten. The AGENTIC note for the nightly
// worker: if a member's own local packs (.claudinite/local_packs/) composed a
// barrier by importing the shared engine, convert each to the contribution
// shape — move the barrier object (id, edges, description, why, doc,
// crossingExcuse, gateDir) onto the local pack's manifest under
// `contributes` and add the mechanism pack to its `requires`. A local pack
// still importing the removed export fails loudly at pack discovery (the
// runner's fail-soft config finding names the broken manifest) — that
// diagnostic is the member-side signal. Consumers with no such local packs
// need nothing.
//
// retire: 'auto' — the durable enforcement is the check, which every member
// runs from its own snapshot; this record only carries the one-time
// conversion guidance through the fleet's next cycles.
export default {
  id: 'pack-independence',
  landed: '2026-07-19',
  summary: 'packs compose by declaration + contributed config, never code imports; local packs that imported the shared barrier engine convert to `contributes` on their manifest',
  // The AGENTIC note above, now machine-readable (agent-preprocessing DESIGN §7):
  // baselining's deterministic preprocessing detects this and escalates to the
  // agent stage instead of advancing the stamp past it. There are no mechanical
  // member-side ops, so this is the record's whole member-side work.
  agentic: {
    model: 'sonnet',
    instructions: 'If a member local pack (.claudinite/local/packs/) composed a barrier by importing the shared engine, convert it to the contribution shape: move the barrier object (id, edges, description, why, doc, crossingExcuse, gateDir) onto the local pack manifest under `contributes`, and add the mechanism pack to its `requires`. A member with no such local pack needs nothing.',
  },
};

== .claudinite/shared/migrations/active_migrations/2026-07-31-static-site-vendoring.mjs ==
// The static-website pack's release pipeline lives in the pack (packs/static-website/stubs/)
// and RUNS from each site repo's own .github/ — GitHub resolves a reusable workflow or a
// composite action only from the repo's own .github/, never from the shared mount. So every
// site repo hosts a MANAGED copy: the pack owns the content, the repo owns the file.
//
// This record is what makes "edit the pack, not the copy" true after adoption. The apply pass
// re-materializes the whole set on every cycle, so a hand-edited or stale copy self-heals and a
// canon fix reaches all three site repos the night it lands (#609).
//
// STANDING, NOT TRANSITIONAL — and that is why `retire: 'manual'`. Every other record here
// moves the fleet OFF an old shape and dies when the last repo has moved; this one has no old
// shape to leave behind (`legacyPresent` is false everywhere by construction), so the retire
// pass would otherwise stage its deletion after one quiet cycle and silently end the sync.
// If a general "keep a pack's vendored set current" mechanism is ever built, this record is
// what it replaces.
//
// The gate is the orchestrator's `name:`, so this only touches a repo that has actually adopted
// the standard (adoption vendors the set once; this keeps it current). Claudinite itself carries
// no such workflow, so the canon never self-applies.
const STUB = '.github/workflows/static-site-release.yml';
const S = 'packs/static-website/stubs';

export default {
  id: 'static-site-vendoring',
  landed: '2026-07-31',
  summary: 'static-website release pipeline kept byte-current in each site repo own .github/ (#609)',

  appliesTo: async (read) => {
    const text = await read(STUB);
    if (!text) return false;
    return /^name:\s*['"]?Release static site['"]?\s*$/m.test(text);
  },

  materialize: [
    { template: `${S}/workflows/static-site-release.yml`, dest: STUB },
    { template: `${S}/workflows/static-site-publish.yml`, dest: '.github/workflows/static-site-publish.yml' },
    { template: `${S}/workflows/static-site-deploy-pages.yml`, dest: '.github/workflows/static-site-deploy-pages.yml' },
    { template: `${S}/workflows/static-site-ci.yml`, dest: '.github/workflows/static-site-ci.yml' },
    { template: `${S}/actions/read-site-config/action.yml`, dest: '.github/actions/read-site-config/action.yml' },
    { template: `${S}/actions/read-site-config/read-config.mjs`, dest: '.github/actions/read-site-config/read-config.mjs' },
    { template: `${S}/actions/bump-site-version/action.yml`, dest: '.github/actions/bump-site-version/action.yml' },
    { template: `${S}/actions/bump-site-version/bump.mjs`, dest: '.github/actions/bump-site-version/bump.mjs' },
    { template: `${S}/actions/assemble-site/action.yml`, dest: '.github/actions/assemble-site/action.yml' },
  ],

  // Nothing to leave behind: this record exists to keep copies current, not to move a repo off
  // an older shape.
  legacyPresent: async () => false,
  retire: 'manual',
};

// This repo's own pack: conventions for the claudinite.com marketing site and
// for maintaining this repo's Claudinite mount. Prose + one bundled skill, no
// structural fingerprint of its own — the declaration in .claudinite-checks.json
// is authoritative (detect: null skips the drift check in both directions).
import nodeTestDiscovery from './node-test-discovery.mjs';

export default {
  id: 'claudinite-website',
  ruleRoutingGuidance: {
    belongs: "conventions for the claudinite.com marketing site and for maintaining this repo's Claudinite mount",
    excludes: 'general site markup and product research — those are html and product-wiki',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [nodeTestDiscovery],
  skills: ['site-visual-check'],
};

import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../../shared/engine/checks/helpers/github-workflows.mjs';

// WHY. Node's default test discovery skips dot-directories outright, and every
// test this repo has lives under `.claudinite/`. So a `node --test` that names
// no path finds nothing, reports success, and reads exactly like a passing
// suite — the failure mode is a green tick over zero assertions, which no
// human and no CI log inspection reliably catches.
//
// The same silent-green also arrives one step later: an invocation that DOES
// name a path, but whose glob or directory matches no file in the tree (a typo,
// a moved fixture, a pack renamed). That is why this rule asserts the stronger
// property — the invocation's arguments must resolve to something that exists —
// rather than merely "an argument was passed". Watching the run go green is
// never the confirmation; a statically non-empty argument set is.
//
// SCOPE. The command surfaces a run can be spelled on: `package.json` scripts
// (the local invocation) and `.github/workflows/*.yml` (the CI step). A command
// carrying shell interpolation (`$…`, backticks) is not judged — its arguments
// are not knowable from the artifact, and a check that guesses cries wolf.

const SHARED_PREFIX = '.claudinite/shared/';

// A shell command's tokens, quotes stripped. Deliberately naive: the commands
// this rule reads are short literal invocations, and anything with substitution
// in it is skipped before we get here.
function tokenize(command) {
  return command.trim().split(/\s+/).filter(Boolean).map((t) => t.replace(/^['"]|['"]$/g, ''));
}

// Split a script body / run: line into individual commands on the shell's
// separators, so `npm ci && node --test` is judged as its two commands.
function commands(text) {
  return text.split(/\n|&&|\|\||[;|]/g);
}

// A glob token as a regex over '/'-separated repo paths: `**` crosses
// directories, `*` and `?` do not.
function globToRegExp(pattern) {
  let out = '';
  for (let i = 0; i < pattern.length; i += 1) {
    const c = pattern[i];
    if (c === '*') {
      if (pattern[i + 1] === '*') {
        // `**/` may match zero directories, so the following slash is optional.
        i += 1;
        if (pattern[i + 1] === '/') { i += 1; out += '(?:.*/)?'; } else out += '.*';
      } else out += '[^/]*';
    } else if (c === '?') out += '[^/]';
    else out += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${out}$`);
}

// Does this argument name at least one file that exists in the repo — as a
// glob, an exact path, or a directory holding files?
export function resolvesToFiles(arg, paths) {
  if (!arg) return false;
  if (/[*?[\]]/.test(arg)) {
    const re = globToRegExp(arg);
    return paths.some((p) => re.test(p));
  }
  const clean = arg.replace(/\/+$/, '');
  return paths.some((p) => p === clean || p.startsWith(`${clean}/`));
}

// The invocations of `node --test` in one command string, and whether each
// one's arguments resolve. Exported for the fixture.
export function judgeCommand(command, paths) {
  if (/[$`]/.test(command)) return null; // interpolated — not knowable from the artifact
  const tokens = tokenize(command);
  const nodeAt = tokens.findIndex((t) => t === 'node' || t.endsWith('/node'));
  if (nodeAt < 0) return null;
  const args = tokens.slice(nodeAt + 1);
  if (!args.includes('--test')) return null;
  // Flags are skipped; every other token is a candidate path. A flag's separate
  // value can only ever make the rule quieter, never noisier.
  const positional = args.filter((t) => !t.startsWith('-'));
  return { ok: positional.some((a) => resolvesToFiles(a, paths)) };
}

const rule = {
  id: 'claudinite-website/node-test-discovery',
  severity: 'blocking',
  description: 'A `node --test` invocation must name test paths that exist — default discovery skips this repo\'s dot-directories',
  doc: '.claudinite/local/packs/claudinite-website/RULES.md',
  why: "Node's test discovery ignores dot-directories, and every test here lives under `.claudinite/` — an invocation that names no existing path runs zero tests and exits green, which is indistinguishable from a passing suite",

  run(ctx) {
    // Tracked ∪ scanned: `ctx.tracked` is the whole tree in either mode, and
    // `ctx.files` adds the not-yet-committed ones — a test file added in the
    // same change as the step that runs it must resolve, or the rule fires on
    // the very commit that fixes it.
    const paths = [...new Set([...ctx.tracked, ...(ctx.files || [])])]
      .filter((f) => !f.startsWith(SHARED_PREFIX));
    const out = [];

    const report = (file, line, command) => out.push(finding(rule, {
      file,
      line,
      what: `\`${command.trim()}\` names no test path that exists in the tree, so it discovers nothing and exits green`,
      fix: "pass an explicit path or glob for the tests, e.g. `node --test '.claudinite/local/packs/**/*.test.mjs'`, and confirm the run's test count is non-zero",
    }));

    const pkg = ctx.read('package.json');
    if (pkg !== null) {
      let scripts = {};
      try { scripts = JSON.parse(pkg).scripts || {}; } catch { scripts = {}; }
      const lines = pkg.split('\n');
      for (const [name, body] of Object.entries(scripts)) {
        if (typeof body !== 'string') continue;
        for (const command of commands(body)) {
          const verdict = judgeCommand(command, paths);
          if (verdict && !verdict.ok) {
            const at = lines.findIndex((l) => l.includes(`"${name}":`));
            report('package.json', at < 0 ? null : at + 1, command);
          }
        }
      }
    }

    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        for (const command of commands(lines[i])) {
          const verdict = judgeCommand(command, paths);
          if (verdict && !verdict.ok) report(wf, i + 1, command);
        }
      }
    }

    return out;
  },
};

